INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robot-wars---extreme-destruction-emode7', 'GAMEBOYADVANCE', 'Robot Wars - Extreme Destruction (E)(Mode7)', '2003', 'Action', 'Warthog Games', '1', 'Robot Combat Action', 'Arena-based robot combat with customization and destruction.', 'Build a combat robot and win the championship tournament.', 'Tactical and destructive robot arena combat.', 'Robot Wars: Extreme Destruction takes the combat to a new level with more parts and tougher arenas. Customize your bot and survive the mechanical carnage to become the champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robotech---the-macross-saga-umode7', 'GAMEBOYADVANCE', 'Robotech - The Macross Saga (U)(Mode7)', '2002', 'Action', 'Lucky Chicken Games', '1', 'Anime Shooter', 'Side-scrolling shoot ''em up with transforming mecha.', 'Defeat the Zentradi forces and protect the Macross.', 'Iconic mecha action based on the classic anime.', 'Robotech: The Macross Saga features fast-paced shooting and the ability to transform your Veritech fighter. Experience the epic sci-fi story through challenging handheld levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robots-ecaravan', 'GAMEBOYADVANCE', 'Robots (E)(Caravan)', '2005', 'Platform', 'Traveller''s Tales', '1', 'Movie-Based Platformer', '2D platformer with gadget-based puzzles and exploration.', 'Help Rodney Copperbottom save the robot world from Ratchet.', 'Fun and mechanical adventure based on the film.', 'Robots for GBA lets you explore a world of metal and gears. Use Rodney''s unique gadgets to solve puzzles and defeat scrap-hungry enemies in this polished movie-based platformer.');
