INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rock-em-sock-em-robots-eindependent', 'GAMEBOYADVANCE', 'Rock ''Em Sock ''Em Robots (E)(Independent)', '2006', 'Action', 'ToyQuest', '2', 'Arcade Fighting Game', 'Arena-based boxing with mechanical robots.', 'Knock the head off your opponent''s robot to win the match.', 'Classic plastic-robot boxing action for GBA.', 'Rock ''Em Sock ''Em Robots brings the iconic toy to life. Choose your robot, master the jabs and power punches, and aim for the "Red Rocker" knockout in this fun and nostalgic handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rock-em-sock-em-robots-usir-vg', 'GAMEBOYADVANCE', 'Rock ''Em Sock ''Em Robots (U)(Sir VG)', '2006', 'Action', 'ToyQuest', '2', 'Arcade Fighting Game', 'Arena-based boxing with mechanical robots.', 'Knock the head off your opponent''s robot to win the match.', 'Classic plastic-robot boxing action for GBA.', 'Rock ''Em Sock ''Em Robots brings the iconic toy to life. Choose your robot, master the jabs and power punches, and aim for the "Red Rocker" knockout in this fun and nostalgic handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rock-n-roll-racing-edosenpfand', 'GAMEBOYADVANCE', 'Rock n'' Roll Racing (E)(Dosenpfand)', '2003', 'Racing', 'Silicon & Synapse', '4', 'Isometric Combat Racing', 'Isometric combat racing with licensed heavy metal music.', 'Win races across alien planets while destroying rival cars.', 'Legendary combat racing with a killer soundtrack.', 'Rock n'' Roll Racing is an arcade classic on GBA. Upgrade your vehicle with missiles and turbo boosts while drifting through treacherous tracks to the tunes of Black Sabbath and Deep Purple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rock-n-roll-racing-uvenom', 'GAMEBOYADVANCE', 'Rock n'' Roll Racing (U)(Venom)', '2003', 'Racing', 'Silicon & Synapse', '4', 'Isometric Combat Racing', 'Isometric combat racing with licensed heavy metal music.', 'Win races across alien planets while destroying rival cars.', 'Legendary combat racing with a killer soundtrack.', 'Rock n'' Roll Racing is an arcade classic on GBA. Upgrade your vehicle with missiles and turbo boosts while drifting through treacherous tracks to the tunes of Black Sabbath and Deep Purple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocket-power---beach-bandits-uvenom', 'GAMEBOYADVANCE', 'Rocket Power - Beach Bandits (U)(Venom)', '2002', 'Action', 'Altron', '1', 'Cartoon Sports Action', 'Action-adventure featuring various extreme sports.', 'Solve the mystery of the missing sand and save the beach.', 'Extreme sports adventure based on the Nicktoon.', 'Rocket Power: Beach Bandits lets you skate, bike, and surf through an engaging story. Help the gang stop a corporate villain from ruining Ocean Shores in this vibrant multi-sport GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocket-power---dream-scheme-umode7', 'GAMEBOYADVANCE', 'Rocket Power - Dream Scheme (U)(Mode7)', '2001', 'Action', 'Altron', '1', 'Cartoon Adventure Game', '2D side-scrolling platformer with skateboarding mechanics.', 'Rescue the gang from Otto''s weird dreams and stop Dr. Stimpleton.', 'Surreal dream-world adventure with the Rocket Power gang.', 'Rocket Power: Dream Scheme features clever level designs that blend platforming with extreme sports. Navigate through Otto''s nightmares and use your board to reach new heights in this fun Nickelodeon tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocket-power---le-cauchemar-dotto-fpatience', 'GAMEBOYADVANCE', 'Rocket Power - Le Cauchemar d''Otto (F)(Patience)', '2002', 'Action', 'Altron', '1', 'Cartoon Adventure Game', '2D side-scrolling platformer with skateboarding mechanics.', 'Rescue the gang from Otto''s weird dreams and stop Dr. Stimpleton.', 'Surreal dream-world adventure with the Rocket Power gang.', 'Rocket Power: Le Cauchemar d''Otto is the French version of Dream Scheme. Experience the same high-flying skating action and creative dreamscapes on your Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocket-power---zero-gravity-zone-umode7', 'GAMEBOYADVANCE', 'Rocket Power - Zero Gravity Zone (U)(Mode7)', '2002', 'Action', 'Altron', '1', 'Cartoon Sports Action', 'Top-down skateboarding and stunt-based action.', 'Master the zero-gravity park and win the ultimate tournament.', 'High-tech extreme sports action with the gang.', 'Rocket Power: Zero Gravity Zone takes skating to the next level. Perform gravity-defying tricks and outscore your rivals in futuristic skate parks in this fast-paced GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-&-crystal', 'GAMEBOYADVANCE', 'Rockman & Crystal', '2021', 'Action', 'Fan Hack', '1', 'Crossover ROM Hack', '2D side-scrolling action platformer (Fan-made/Hack).', 'Defeat the crystal-themed robot masters and save the city.', 'A unique crystal-themed twist on classic Rockman.', 'Rockman & Crystal is a creative fan-made modification. It features altered sprites and new level aesthetics, providing a fresh visual challenge for fans of the Blue Bomber’s classic GBA adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-&-forte-jeurasia', 'GAMEBOYADVANCE', 'RockMan & Forte (J)(Eurasia)', '2003', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling action platformer with two playable heroes.', 'Stop the scientist Regas and protect the world from destruction.', 'Legendary crossover platformer featuring Mega Man and Bass.', 'Rockman & Forte (Mega Man & Bass) is a masterpiece of GBA action. Choose between Rockman''s classic mechanics or Forte''s rapid-fire and double-jump to conquer some of the toughest levels in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-3-jeurasia', 'GAMEBOYADVANCE', 'RockMan EXE 3 (J)(Eurasia)', '2002', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with real-time card battles.', 'Stop the secret society WWW and prevent the Cyber-End.', 'The Japanese original of Battle Network 3.', 'Rockman EXE 3 offers deep strategic combat using Battle Chips. Explore the digital world, customize your Navi, and experience the refined mechanics that made this entry a fan favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-4---tournament-red-sun-jindependent', 'GAMEBOYADVANCE', 'RockMan EXE 4 - Tournament Red Sun (J)(Independent)', '2003', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with real-time card battles.', 'Win the tournament and stop the meteor from hitting Earth.', 'Competitive tournament-style RPG action.', 'Rockman EXE 4 Tournament Red Sun introduces the Soul Unison system. Compete in high-stakes net battles and build a powerful folder of chips in this intense Japanese version of the fourth entry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-4-tournament-blue-moon-jeurasia', 'GAMEBOYADVANCE', 'RockMan EXE 4 Tournament Blue Moon (J)(Eurasia)', '2003', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with real-time card battles.', 'Win the tournament and stop the meteor from hitting Earth.', 'Competitive tournament-style RPG action.', 'Rockman EXE 4 Tournament Blue Moon features exclusive souls and chips. Battle through the tournament and stop a cosmic threat in this strategic and polished GBA JRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-4-tournament-red-sun-jeurasia', 'GAMEBOYADVANCE', 'RockMan EXE 4 Tournament Red Sun (J)(Eurasia)', '2003', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with real-time card battles.', 'Win the tournament and stop the meteor from hitting Earth.', 'Competitive tournament-style RPG action.', 'Rockman EXE 4 Tournament Red Sun features unique bosses and transformation abilities. Master the grid-based combat and prove your skills in the digital arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-45-real-operation-jindependent', 'GAMEBOYADVANCE', 'Rockman EXE 4.5 Real Operation (J)(Independent)', '2004', 'RPG', 'Capcom', '1', 'Action RPG', 'Real-time digital life simulation and strategic battling.', 'Act as a Net-Op and manage MegaMan’s daily schedule and battles.', 'A unique spin-off focusing on real-time Navi interaction.', 'Rockman EXE 4.5 Real Operation lets you interact with your Navi as if it were a real PDA. Schedule activities and participate in automatic battles that test your folder-building skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-45:-real-operation-english', 'GAMEBOYADVANCE', 'Rockman EXE 4.5: Real Operation (English)', '2004', 'RPG', 'Capcom', '1', 'Action RPG', 'Real-time digital life simulation and strategic battling.', 'Act as a Net-Op and manage MegaMan’s daily schedule and battles.', 'The fan-translated English version of the unique sim-RPG.', 'Rockman EXE 4.5 (English) allows western fans to finally enjoy this "real-time" Navi simulator. Choose your Navi, manage their day, and participate in strategic battles in full English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-5---team-of-blues-jcaravan', 'GAMEBOYADVANCE', 'Rockman EXE 5 - Team of Blues (J)(Caravan)', '2004', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with a squad-based "Liberation Mission" system.', 'Lead a team of Navis to liberate the internet from Darkloids.', 'Strategic team-based action in the digital world.', 'Rockman EXE 5 - Team of Blues (Team ProtoMan) introduces team management to the series. Control multiple Navis in strategic grid-based skirmishes to reclaim the net in this polished Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-5---team-of-colonel-jsupplex', 'GAMEBOYADVANCE', 'Rockman EXE 5 - Team of Colonel (J)(Supplex)', '2004', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with a squad-based "Liberation Mission" system.', 'Lead a team of Navis to liberate the internet from Darkloids.', 'Strategic team-based action in the digital world.', 'Rockman EXE 5 - Team of Colonel features a unique storyline and exclusive Navis. Master the Liberation Missions and stop the Darkloids in this deep and challenging GBA RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-6---dennoujuu-faltzer-jsupplex', 'GAMEBOYADVANCE', 'RockMan EXE 6 - Dennoujuu Faltzer (J)(sUppLeX)', '2005', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with the powerful "Beast Out" transformation.', 'Master the power of the Cybeasts and save the net.', 'The final epic chapter of the Battle Network series.', 'Rockman EXE 6 - Dennoujuu Faltzer (Falzar) brings the saga to a close. Use the Faltzer beast power to dominate battles and experience the ultimate evolution of Battle Chip combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-6---dennoujuu-grega-jsupplex', 'GAMEBOYADVANCE', 'RockMan EXE 6 - Dennoujuu Grega (J)(sUppLeX)', '2005', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with the powerful "Beast Out" transformation.', 'Master the power of the Cybeasts and save the net.', 'The final epic chapter of the Battle Network series.', 'Rockman EXE 6 - Dennoujuu Grega (Gregar) features the ferocious Grega transformation. Build your final folder and participate in the series'' most refined tactical combat system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-exe-battlechip-gp-jeurasia', 'GAMEBOYADVANCE', 'Rockman EXE Battlechip GP (J)(Eurasia)', '2005', 'Strategy', 'Capcom', '4', 'Card-Based Strategy', 'Turn-based tactical card game and digital racing hybrid.', 'Win the Grand Prix and become the top BattleChip racer.', 'Strategic card-battling racing spin-off.', 'Rockman EXE Battlechip GP changes the formula into a strategic race. Build a deck of chips that activate automatically during high-speed net-battles to win the tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-zero-jeurasia', 'GAMEBOYADVANCE', 'RockMan Zero (J)(Eurasia)', '2002', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling action-slasher with high-speed combat.', 'Lead the Resistance to save the Reploids from Neo Arcadia.', 'Intense and stylish action platformer for GBA.', 'Rockman Zero (Mega Man Zero) redefined the franchise with a darker tone and Z-Saber focused combat. Master the high-speed dashing and precise slashing to survive this brutal but rewarding classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-zero-2-jeurasia', 'GAMEBOYADVANCE', 'RockMan Zero 2 (J)(Eurasia)', '2003', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling action-slasher with high-speed combat.', 'Defeat the Four Guardians and uncover Zero''s true past.', 'Fast-paced and challenging action sequel.', 'Rockman Zero 2 expands the series with the Form system and Chain Rod. Experience even faster combat and more complex level designs in this highly acclaimed handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-zero-3-jeurasia', 'GAMEBOYADVANCE', 'Rockman Zero 3 (J)(Eurasia)', '2004', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling action-slasher with high-speed combat.', 'Stop Dr. Weil and the Omega project to bring peace.', 'Dark and intense action-platforming masterpiece.', 'Rockman Zero 3 is often considered the peak of the series. Featuring the Cyber-elf system and intense boss battles, it offers some of the best 2D action available on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-zero-3-original-x', 'GAMEBOYADVANCE', 'Rockman Zero 3 Original X', '2004', 'Action', 'Capcom', '1', 'Modified ROM Hack', '2D side-scrolling action-slasher (Mod/Hack).', 'Experience the classic Zero 3 journey with X-themed visuals.', 'A visual reimagining of Zero 3 with classic Mega Man X aesthetics.', 'Rockman Zero 3 Original X is a tribute hack that changes Zero''s appearance to resemble his classic Mega Man X counterpart. Play through the epic story with a nostalgic visual twist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-zero-4-jindependent', 'GAMEBOYADVANCE', 'RockMan Zero 4 (J)(Independent)', '2005', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling action-slasher with the new Weather system.', 'Protect the peace of Neo Arcadia and defeat Dr. Weil once and for all.', 'The emotional and high-octane finale to the Zero series.', 'Rockman Zero 4 introduces the "Z-Knuckle" for stealing enemy weapons and a dynamic weather system that alters stage difficulty. Experience the definitive conclusion to Zero''s legendary saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocky-eindependent', 'GAMEBOYADVANCE', 'Rocky (E)(Independent)', '2002', 'Sports', 'Rage Games', '1', 'Boxing Sports Game', '2D side-scrolling boxing with rhythm and timing elements.', 'Fight your way from Philly to the world heavyweight championship.', 'Gritty and cinematic boxing adventure based on the movie.', 'Rocky on GBA captures the spirit of the films. Train your fighter, master the defensive dodges, and unleash powerful combinations in this polished and atmospheric sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocky-uvenom', 'GAMEBOYADVANCE', 'Rocky (U)(Venom)', '2002', 'Sports', 'Rage Games', '1', 'Boxing Sports Game', '2D side-scrolling boxing with rhythm and timing elements.', 'Fight your way from Philly to the world heavyweight championship.', 'Gritty and cinematic boxing adventure based on the movie.', 'Rocky on GBA captures the spirit of the films. Train your fighter, master the defensive dodges, and unleash powerful combinations in this polished and atmospheric sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roland-garros-2002---next-generation-tennis-emode7', 'GAMEBOYADVANCE', 'Roland Garros 2002 - Next Generation Tennis (E)(Mode7)', '2002', 'Sports', 'SCEE Studio', '4', 'Tennis Simulation', '3D-perspective tennis simulation with licensed players.', 'Win the prestigious Roland Garros tournament and become number one.', 'Realistic and challenging handheld tennis simulation.', 'Roland Garros 2002 features smooth animations and a variety of court surfaces. Master the timing of your serves and volleys to conquer the clay courts in this licensed sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rpg-tsukuru-advance-jmugs', 'GAMEBOYADVANCE', 'RPG Tsukuru Advance (J)(Mugs)', '2003', 'RPG', 'Enterbrain', '1', 'RPG Creation Toolkit', 'Game creation tool focusing on the JRPG genre.', 'Create, play, and share your own custom role-playing games.', 'Powerful RPG maker application for the GBA.', 'RPG Tsukuru Advance (RPG Maker Advance) turns your GBA into a development studio. Use a wide variety of assets and a simple scripting system to build your own fantasy adventures from scratch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---all-grown-up-urising-sun', 'GAMEBOYADVANCE', 'Rugrats - All Grown Up (U)(Rising Sun)', '2003', 'Action', 'THQ', '2', 'Cartoon Platformer', 'Mini-game collection and adventure based on the spin-off series.', 'Help the older Rugrats gang complete tasks and win games.', 'Fun adventure featuring the teenage Rugrats characters.', 'Rugrats: All Grown Up! for GBA brings the older versions of Tommy and the gang to life. Play through various mini-games and explore detailed environments in this colorful Nickelodeon adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---castle-capers-sindependent', 'GAMEBOYADVANCE', 'Rugrats - Castle Capers (S)(Independent)', '2001', 'Action', 'THQ', '1', 'Cartoon Platformer', '2D side-scrolling platformer with puzzle elements.', 'Navigate the fantasy castle to rescue the lost toys.', 'Fantasy-themed platforming adventure with the Rugrats.', 'Rugrats: Castle Capers takes the babies on a grand imagination-fueled journey. Explore massive castle-themed levels, solve simple puzzles, and defeat "enemies" in this charming handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---castle-capers-uvenom', 'GAMEBOYADVANCE', 'Rugrats - Castle Capers (U)(Venom)', '2001', 'Action', 'THQ', '1', 'Cartoon Platformer', '2D side-scrolling platformer with puzzle elements.', 'Navigate the fantasy castle to rescue the lost toys.', 'Fantasy-themed platforming adventure with the Rugrats.', 'Rugrats: Castle Capers takes the babies on a grand imagination-fueled journey. Explore massive castle-themed levels, solve simple puzzles, and defeat "enemies" in this charming handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---go-wild-uvenom', 'GAMEBOYADVANCE', 'Rugrats - Go Wild (U)(Venom)', '2003', 'Action', 'THQ', '2', 'Cartoon Adventure Game', 'Adventure and mini-game hybrid based on the movie crossover.', 'Explore the island and survive the jungle alongside the Wild Thornberrys.', 'Jungle adventure based on the Rugrats/Thornberrys movie.', 'Rugrats Go Wild brings the cinematic crossover to GBA. Switch between different characters to solve puzzles, navigate the wilderness, and complete mini-games in this fun tropical quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---i-gotta-go-party-upatience', 'GAMEBOYADVANCE', 'Rugrats - I Gotta Go Party (U)(Patience)', '2002', 'Action', 'THQ', '2', 'Cartoon Party Game', 'Mini-game compilation featuring party-style challenges.', 'Win all the party games and unlock secret collectibles.', 'Fast-paced party game collection with the Rugrats.', 'Rugrats: I Gotta Go Party is packed with variety. From racing to logic puzzles, it offers a series of quick, engaging challenges perfect for fans of the iconic cartoon on the go.');
