INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scourge-the-hedgehog-over-emerl-spanish', 'GAMEBOYADVANCE', 'Scourge The Hedgehog Over Emerl ''[Spanish]''', '2005', 'Action', 'Fan Project', '1', 'Fan-Made Action Hack', '2D action-fighting game featuring Sonic the Hedgehog characters.', 'Defeat opponents in the arena using Scourge''s unique moves.', 'Intense Sonic-themed arena combat in Spanish.', 'Scourge The Hedgehog Over Emerl is a creative Spanish RomHack of Sonic Battle. Play as the anti-Sonic hero, Scourge, with modified sprites and dialogue in this fast-paced handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scrabble-elightforce', 'GAMEBOYADVANCE', 'Scrabble (E)(Lightforce)', '2004', 'Board', 'GameTek', '4', 'Classic Board Game', 'Digital version of the classic word-building board game.', 'Score the most points by creating words on the board.', 'Authentic handheld Scrabble experience.', 'Scrabble for GBA brings the world''s favorite word game to your pocket. Challenge the AI or play with friends in a faithful recreation of the board game experience.');
