INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scrabble-scramble-erising-sun', 'GAMEBOYADVANCE', 'Scrabble Scramble (E)(Rising Sun)', '2005', 'Puzzle', 'Electronic Arts', '4', 'Word Puzzle Game', 'Timed word-building challenges and puzzle modes.', 'Solve word puzzles and beat high scores in various modes.', 'A creative and speedy spin on word games.', 'Scrabble Scramble offers a variety of quick-fire word challenges. Perfect for short play sessions, it tests your vocabulary and speed in several unique handheld modes.');
