INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scurge-hive-erising-sun', 'GAMEBOYADVANCE', 'Scurge Hive (E)(Rising Sun)', '2006', 'Action', 'Orbital Media', '1', 'Sci-Fi Action Adventure', 'Isometric action-adventure with sci-fi themes and combat.', 'Eradicate the Scurge virus and survive the infected planet.', 'Atmospheric sci-fi adventure with intense combat.', 'Scurge: Hive features a beautiful isometric perspective and fast-paced action. Play as bounty hunter Jenosa Arma and use elemental weapons to survive a bio-organic nightmare.');
