INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam-force-jindependent', 'GAMEBOYADVANCE', 'SD Gundam Force (J)(Independent)', '2004', 'Action', 'Natsume', '1', 'Anime Action Game', '2D side-scrolling action game with chibi-style mechas.', 'Fight through robotic armies to save Neotopia.', 'Fun and colorful Gundam action for all ages.', 'SD Gundam Force features the "Super Deformed" cast in an accessible action adventure. Use unique mecha skills and swordplay to defeat the Dark Axis forces on your GBA.');
