INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sea-trader---rise-of-taipan-ueurasia', 'GAMEBOYADVANCE', 'Sea Trader - Rise of Taipan (U)(Eurasia)', '2003', 'Strategy', 'Software 2000', '1', 'Trade Simulation', 'Maritime trade simulation and exploration.', 'Build a shipping empire by trading goods across the seas.', 'Engaging economic strategy and naval exploration.', 'Sea Trader: Rise of Taipan lets you navigate the globe, manage resources, and outsmart pirates. Buy low and sell high in this surprisingly deep handheld trading simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sea-world---shamus-deep-sea-adventure-utrashman', 'GAMEBOYADVANCE', 'Sea World - Shamu''s Deep Sea Adventure (U)(Trashman)', '2005', 'Action', 'Vicarious Visions', '1', 'Marine Adventure Game', 'Underwater action-adventure with educational elements.', 'Complete missions as Shamu to save the ocean environment.', 'Aquatic adventure featuring the world-famous orca.', 'Sea World: Shamu''s Deep Sea Adventure lets you explore the ocean depths. Solve puzzles, perform tricks, and protect marine life in this family-friendly GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sega-arcade-gallery-epatience', 'GAMEBOYADVANCE', 'Sega Arcade Gallery (E)(Patience)', '2002', 'Arcade', 'Sega', '2', 'Classic Arcade Compilation', 'Compilation of four classic Sega arcade hits.', 'Reach high scores in OutRun, After Burner, Space Harrier, and Super Hang-On.', 'Perfect portable versions of legendary arcade games.', 'Sega Arcade Gallery is a must-have for retro fans. Experience four of Sega''s most iconic "Super Scaler" hits with incredible fidelity on the Game Boy Advance hardware.');
