INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sennen-kazoku-jsupplex', 'GAMEBOYADVANCE', 'Sennen Kazoku (J)(Supplex)', '2005', 'Simulation', 'Nintendo', '1', 'Life Simulation', 'Unique "Family Life" simulation with a long-term focus.', 'Guide generations of a family through life''s ups and downs.', 'Innovative and artistic family management sim.', 'Sennen Kazoku (Thousand Year Family) is a rare GBA gem from Nintendo. Act as a guardian spirit and observe your family''s history across centuries in this peaceful and beautiful simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sentouin---yamada-hajime-jrising-sun', 'GAMEBOYADVANCE', 'Sentouin - Yamada Hajime (J)(Rising Sun)', '2002', 'Action', 'Media Rings', '1', 'Comedy Action Game', 'Comedic action-adventure with mini-games and quirky tasks.', 'Help the bumbling protagonist complete missions in his daily life.', 'Humorous Japanese adventure starring Yamada Hajime.', 'Sentouin - Yamada Hajime is a quirky Japanese title filled with personality. Navigate through various comedic scenarios and solve puzzles in this unique and visually distinct GBA experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('serious-sam-advance-egba', 'GAMEBOYADVANCE', 'Serious Sam Advance (E)(GBA)', '2004', 'Shooter', 'Climax', '1', 'First-Person Shooter', 'First-person shooter (FPS) with 3D environments and hordes of enemies.', 'Blast your way through ancient Egypt to stop Mental’s army.', 'Intense, high-octane 3D shooting action on GBA.', 'Serious Sam Advance pushes the GBA hardware to its limits with a 3D engine. Face off against hundreds of aliens across massive levels in this faithful portable version of the chaotic PC classic.');
