INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shaman-king-chou-senjiryokketsu-3-jeurasia', 'GAMEBOYADVANCE', 'Shaman King Chou Senjiryokketsu 3 (J)(Eurasia)', '2004', 'Action', 'Bandai', '1', 'Anime Action Game', 'Strategic card-battle JRPG based on the Shaman King universe.', 'Build a powerful deck and win the Shaman card tournament.', 'Tactical anime card-battling experience.', 'Shaman King Chou Senjiryokketsu 3 features deep deck-building mechanics. Collect rare cards and use strategic maneuvers to defeat rival shamans in this polished Japanese exclusive.');
