INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shanghai-jrising-sun', 'GAMEBOYADVANCE', 'Shanghai (J)(Rising Sun)', '1999', 'Puzzle', 'Sunsoft', '2', 'Classic Tile Puzzle', 'Tile-matching puzzle game based on the classic Mahjong Solitaire.', 'Clear the board by matching identical pairs of tiles.', 'Relaxing and challenging handheld tile puzzle game.', 'Shanghai brings the timeless logic of Mahjong Solitaire to your pocket. Master hundreds of layouts and test your speed in this classic and addictive handheld puzzle experience.');
