INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shaun-palmers-pro-snowboarder-umenace', 'GAMEBOYADVANCE', 'Shaun Palmer''s Pro Snowboarder (U)(Menace)', '2002', 'Sports', 'Neversoft', '2', 'Extreme Sports Snowboarding', 'Extreme sports simulation with tricks and pro-circuit racing.', 'Outscore your rivals and win the snowboarding championship.', 'Fast-paced and flashy snowboarding action for GBA.', 'Shaun Palmer''s Pro Snowboarder brings the Tony Hawk engine to the snow. Execute massive grabs and grinds on realistic mountains in this high-adrenaline extreme sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sheep-emode7', 'GAMEBOYADVANCE', 'Sheep (E)(Mode7)', '2001', 'Puzzle', 'Zoo Digital', '1', 'Logic Puzzle Game', 'Isometric puzzle-strategy game with sheep-herding mechanics.', 'Herd your flock safely through dangerous and trap-filled levels.', 'Quirky and challenging sheep-herding puzzle game.', 'Sheep is a unique strategic title where you must guide your flock past obstacles. Avoid predators and environmental hazards in this creative and often humorous GBA puzzle adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shifting-gears---road-trip-urising-sun', 'GAMEBOYADVANCE', 'Shifting Gears - Road Trip (U)(Rising Sun)', '2002', 'Racing', 'Electronic Arts', '2', 'Arcade Racing', 'Arcade-style racing with vehicle customization and speed.', 'Win the ultimate road trip by finishing first in various races.', 'Fun and fast-paced arcade racing action.', 'Shifting Gears: Road Trip focuses on pure speed and accessibility. Choose your car, upgrade its parts, and dominate a variety of tracks across the country in this entertaining GBA racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shikakui-atama-wo-marukusuru-advance---kanji-keisan-jindependent', 'GAMEBOYADVANCE', 'Shikakui Atama wo Marukusuru Advance - Kanji Keisan (J)(Independent)', '2001', 'Educational', 'Nintendo', '1', 'Brain Training', 'Educational brain-training game focusing on Kanji and Math.', 'Improve your mental skills through a series of school-based tasks.', 'Challenging Japanese educational and brain-training game.', 'Shikakui Atama wo Marukusuru Advance focuses on building core academic skills. Test your knowledge of Kanji and mathematics in this helpful learning tool for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shikakui-atama-wo-marukusuru-advance---kokugo-sansu-rika-shakai-jindependent', 'GAMEBOYADVANCE', 'Shikakui Atama wo Marukusuru Advance - Kokugo Sansu Rika Shakai (J)(Independent)', '2001', 'Educational', 'Nintendo', '1', 'Brain Training', 'Educational brain-training game focusing on school subjects.', 'Master various subjects like Science and Social Studies.', 'Comprehensive Japanese educational quiz and training game.', 'This version of Shikakui Atama wo Marukusuru covers a wide range of academic topics. Perfect for students, it offers an engaging way to practice school subjects on a handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shimura-ken-no-bakatonosama-jpolla', 'GAMEBOYADVANCE', 'Shimura Ken no Bakatonosama (J)(Polla)', '2001', 'Action', 'Hudson Soft', '1', 'Comedy Action Game', 'Comedic mini-game collection based on the Japanese variety show.', 'Complete wacky challenges to entertain the Lord.', 'Surreal and funny Japanese comedy mini-games.', 'Shimura Ken no Bakatonosama captures the spirit of the famous TV show. Engage in absurd humor and creative mini-games in this delightful Japanese-exclusive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-bokura-no-taiyou---gyakushuu-no-sabata-jsupplex', 'GAMEBOYADVANCE', 'Shin Bokura no Taiyou - Gyakushuu no Sabata (J)(Supplex)', '2004', 'Action', 'Konami', '1', 'Vampire Action Adventure', 'Action-RPG with stealth and solar-sensor based mechanics.', 'Defeat the vampires and stop the undying threat of Sabata.', 'Legendary Hideo Kojima produced vampire-hunting RPG.', 'Shin Bokura no Taiyou (Boktai 3) is a masterpiece of GBA action. Featuring deep combat and a unique atmosphere, it continues the epic saga of Solar Boy Django in this Japan-only sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-kisekae-monogatari-jrising-sun', 'GAMEBOYADVANCE', 'Shin Kisekae Monogatari (J)(Rising Sun)', '2001', 'Simulation', 'Nintendo', '1', 'Fashion Simulation', 'Lifestyle simulation and fashion-based adventure.', 'Customize your character and interact with a vibrant world.', 'Charming Japanese fashion and life simulation.', 'Shin Kisekae Monogatari allows players to express their style through deep character customization. Engage in social activities and follow a sweet narrative in this polished GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei---devil-children---hikari-no-sho-jcezar', 'GAMEBOYADVANCE', 'Shin Megami Tensei - Devil Children - Hikari no Sho (J)(Cezar)', '2002', 'RPG', 'Atlus', '1', 'Monster-Collecting RPG', 'Monster-collecting turn-based RPG with a lighthearted SMT tone.', 'Save the world of the Devil Children by taming demons.', 'Accessible and deep demon-collecting JRPG.', 'Shin Megami Tensei: Devil Children - Hikari no Sho (Demikids Light) offers a more accessible entry into the SMT universe. Collect, fuse, and battle demons in this colorful and strategic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei---devil-children---puzzle-de-call-jbatman', 'GAMEBOYADVANCE', 'Shin Megami Tensei - Devil Children - Puzzle de Call (J)(BatMan)', '2001', 'Puzzle', 'Atlus', '1', 'Monster Puzzle Game', 'Puzzle-adventure featuring characters from the Devil Children series.', 'Solve tile-matching puzzles to progress through the story.', 'Creative demon-themed puzzle game for GBA.', 'Shin Megami Tensei: Devil Children - Puzzle de Call blends the lore of the series with addictive puzzle gameplay. Match blocks and use demon skills to clear levels in this unique spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei---devil-children---yami-no-sho-jcezar', 'GAMEBOYADVANCE', 'Shin Megami Tensei - Devil Children - Yami no Sho (J)(Cezar)', '2002', 'RPG', 'Atlus', '1', 'Monster-Collecting RPG', 'Monster-collecting turn-based RPG with a lighthearted SMT tone.', 'Save the world of the Devil Children by taming demons.', 'Accessible and deep demon-collecting JRPG.', 'Shin Megami Tensei: Devil Children - Yami no Sho (Demikids Dark) features exclusive demons and a darker perspective on the story. Master the art of demon fusion in this deep handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei---devil-children-2---honoo-no-sho-jrising-sun', 'GAMEBOYADVANCE', 'Shin Megami Tensei - Devil Children 2 - Honoo no Sho (J)(Rising Sun)', '2003', 'RPG', 'Atlus', '1', 'Monster-Collecting RPG', 'Monster-collecting turn-based RPG with a lighthearted SMT tone.', 'Stop the war between worlds and collect powerful demons.', 'Polished sequel to the popular Demikids series.', 'Shin Megami Tensei: Devil Children 2 - Honoo no Sho (Fire Book) expands the demon roster and refines the battle mechanics. It’s a must-play for fans of strategic monster-battling RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei---devil-children-2---koori-no-sho-jrising-sun', 'GAMEBOYADVANCE', 'Shin Megami Tensei - Devil Children 2 - Koori no Sho (J)(Rising Sun)', '2003', 'RPG', 'Atlus', '1', 'Monster-Collecting RPG', 'Monster-collecting turn-based RPG with a lighthearted SMT tone.', 'Stop the war between worlds and collect powerful demons.', 'Polished sequel to the popular Demikids series.', 'Shin Megami Tensei: Devil Children 2 - Koori no Sho (Ice Book) offers a parallel story with unique demons. Experience the deep narrative and addictive collection loop of this Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei---devil-children-messiah-riser-jcaravan', 'GAMEBOYADVANCE', 'Shin Megami Tensei - Devil Children Messiah Riser (J)(Caravan)', '2004', 'RPG', 'Atlus', '1', 'Monster-Collecting RPG', 'Strategic JRPG focused on the Messiah legend within the SMT world.', 'Lead the chosen ones to victory against demonic forces.', 'Strategic and story-heavy Shin Megami Tensei spin-off.', 'Shin Megami Tensei: Devil Children Messiah Riser features tactical combat and a compelling plot. Navigate a world in crisis and harness the power of demons in this refined GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-jpolla', 'GAMEBOYADVANCE', 'Shin Megami Tensei (J)(Polla)', '2003', 'RPG', 'Atlus', '1', 'Dungeon Crawling RPG', 'Traditional turn-based JRPG with a focus on negotiation and fusion.', 'Survive a post-apocalyptic Tokyo and decide the fate of humanity.', 'Hardcore and atmospheric legendary RPG for GBA.', 'Shin Megami Tensei on GBA is a faithful port of the original masterpiece. Experience the dark atmosphere, complex demon negotiation, and the alignment system that defined the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-megami-tensei-2-jrising-sun', 'GAMEBOYADVANCE', 'Shin Megami Tensei 2 (J)(Rising Sun)', '1992', 'RPG', 'Atlus', '1', 'Classic Dungeon RPG', 'First-person dungeon crawler JRPG with demon negotiation.', 'Navigate a dystopian future and choose between Law, Chaos, or Neutrality.', 'Dark and philosophical masterpiece of the SMT series.', 'Shin Megami Tensei 2 for GBA is a faithful port of the SNES classic. Experience a deep, adult narrative set in Tokyo Millennium where your choices decide the ultimate fate of humanity and the divine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-nihon-pro-wrestling-toukon-retsuden-advance-jmugs', 'GAMEBOYADVANCE', 'Shin Nihon Pro Wrestling Toukon Retsuden Advance (J)(Mugs)', '2003', 'Sports', 'Yuke''s', '2', 'Professional Wrestling', '3D-style wrestling simulation with a tactical focus.', 'Win the New Japan Pro Wrestling championship belt.', 'Authentic Japanese professional wrestling on GBA.', 'Shin Nihon Pro Wrestling Toukon Retsuden Advance features real NJPW stars and a technical grappling system. Master the timing of your strikes and submissions to dominate the ring.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-sangoku-musou-advance-jcaravan', 'GAMEBOYADVANCE', 'Shin Sangoku Musou Advance (J)(Caravan)', '2005', 'Action Koei', '1', 'Hack and Slash Action', NULL, 'Isometric hack-and-slash action with tactical map elements.', 'Defeat thousands of soldiers and conquer ancient China.', 'Dynasty Warriors style action adapted for handheld.', 'Shin Sangoku Musou Advance brings the "one vs. thousands" excitement to the GBA. Choose legendary officers and clear entire battlefields with powerful Musou attacks in this strategic action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinchan-aventuras-en-cineland-strashman', 'GAMEBOYADVANCE', 'Shinchan Aventuras en Cineland (S)(Trashman)', '2004', 'Action', 'Artoon', '1', 'Cartoon Platformer', '2D side-scrolling platformer with mini-games and humor.', 'Help Shin-chan navigate movie-themed worlds to save the day.', 'Fun and wacky platforming based on the movie.', 'Shinchan: Aventuras en Cineland offers a charming and hilarious experience. Use Shin-chan''s unique costumes and abilities to overcome obstacles in this polished Spanish-language adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinchan-contra-los-munecos-de-shock-gahn-sindependent', 'GAMEBOYADVANCE', 'Shinchan contra los Munecos de Shock Gahn (S)(Independent)', '2004', 'Action', 'Artoon', '1', 'Cartoon Platformer', '2D side-scrolling platformer with costume-based powers.', 'Stop the evil Shock Gahn dolls and protect Kasukabe.', 'Action-packed platformer starring the mischievous Shin-chan.', 'Shinchan contra los Muñecos de Shock Gahn features creative level designs and funny dialogue. Collect items and transform Shin-chan to defeat bizarre enemies in this fan-favorite GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shingata-medarot---kabuto-version-jcaravan', 'GAMEBOYADVANCE', 'Shingata Medarot - Kabuto Version (J)(Caravan)', '2004', 'RPG', 'Natsume', '1', 'Monster Collecting RPG', 'Turn-based RPG with customizable robot parts (Medarots).', 'Build the ultimate Medarot and win the Robattle tournament.', 'Deep robotic customization and strategic battling.', 'Shingata Medarot: Kabuto Version focuses on long-range combat. Collect hundreds of parts from defeated enemies to upgrade your robot in this refreshed version of the classic series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shingata-medarot---kuwagata-version-jcaravan', 'GAMEBOYADVANCE', 'Shingata Medarot - Kuwagata Version (J)(Caravan)', '2004', 'RPG', 'Natsume', '1', 'Monster Collecting RPG', 'Turn-based RPG with customizable robot parts (Medarots).', 'Build the ultimate Medarot and win the Robattle tournament.', 'Deep robotic customization and strategic battling.', 'Shingata Medarot: Kuwagata Version emphasizes close-quarters melee combat. Customize your Medarot’s head, arms, and legs to create a unique and powerful robotic fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shining-force---kuroki-ryuu-no-fukkatsu-jindependent', 'GAMEBOYADVANCE', 'Shining Force - Kuroki Ryuu no Fukkatsu (J)(Independent)', '2004', 'RPG', 'Neverland', '1', 'Tactical Fantasy RPG', 'Turn-based tactical RPG with grid-based movement.', 'Lead the Shining Force to prevent the resurrection of the Dark Dragon.', 'A masterful remake of the legendary strategy RPG.', 'Shining Force: Resurrection of the Dark Dragon is a GBA standout. Featuring new characters, a refined card system, and beautiful sprites, it''s the definitive way to play this tactical classic.');
