INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinyaku-seiken-densetsu-jindependent', 'GAMEBOYADVANCE', 'Shinyaku Seiken Densetsu (J)(Independent)', '2003', 'Action RPG', 'Brownie Brown', '1', 'Action RPG Fantasy', 'Action-RPG remake of the classic Final Fantasy Adventure.', 'Protect the Mana Tree and save the world from the empire.', 'Beautifully crafted remake of the Mana series origins.', 'Shinyaku Seiken Densetsu (Sword of Mana) features stunning 2D graphics and a deep class system. Experience the emotional story and fluid real-time combat that the series is famous for.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shiren-monsters-netsal-jrising-sun', 'GAMEBOYADVANCE', 'Shiren Monsters Netsal (J)(Rising Sun)', '2004', 'RPG', 'Chunsoft', '1', 'Roguelike Monster RPG', 'Sports simulation mixed with monster collection and strategy.', 'Manage a team of monsters and win the soccer league.', 'Unique and addictive monster-soccer hybrid.', 'Shiren Monsters: Netsal is a creative spin-off from the Mystery Dungeon series. Recruit monsters, train them in sports, and use strategic plays to win matches in this charming Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shonen-jumps---one-piece-utrashman', 'GAMEBOYADVANCE', 'Shonen Jump''s - One Piece (U)(Trashman)', '2005', 'Action', 'Bandai', '1', 'Anime Action Adventure', '2D side-scrolling beat ''em up and action-adventure.', 'Help Luffy find the legendary treasure, the One Piece.', 'High-seas action based on the legendary anime.', 'Shonen Jump''s One Piece for GBA features fast combat and platforming. Play as Luffy, use his rubber powers to defeat enemies, and explore the Grand Line in this vibrant handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shonen-jumps-shaman-king---master-of-spirits-2-utrashman', 'GAMEBOYADVANCE', 'Shonen Jump''s Shaman King - Master of Spirits 2 (U)(Trashman)', '2005', 'Action', 'Konami', '1', 'Anime Action Platformer', '2D Metroidvania-style action platformer with spirit abilities.', 'Navigate a massive map and defeat powerful Shamans.', 'Incredible action platformer with deep spirit mechanics.', 'Shaman King: Master of Spirits 2 is a high-quality Metroidvania. Use the souls of defeated enemies to gain new abilities and explore hidden areas in this beautifully animated GBA sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shrek---reekin-havoc-eindependent', 'GAMEBOYADVANCE', 'Shrek - Reekin'' Havoc (E)(Independent)', '2003', 'Action', 'Artificial Mind', '1', 'Cartoon Action Platformer', '2D side-scrolling action platformer with multiple characters.', 'Help Shrek and his friends stop a fairy tale disaster.', 'Fun and chaotic platforming featuring the ogre.', 'Shrek: Reekin'' Havoc features multiple playable characters like Shrek and Donkey. Navigate through 30 levels of ogre-sized action and defeat iconic fairy tale villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shrek---smash-n-crash-racing-urising-sun', 'GAMEBOYADVANCE', 'Shrek - Smash n'' Crash Racing (U)(Rising Sun)', '2006', 'Racing', 'Torus Games', '4', 'Cartoon Arcade Racing', 'Arcade-style kart racing with items and hazards.', 'Win the swamp championship and defeat rival fairy tale racers.', 'Fast-paced kart racing featuring Shrek characters.', 'Shrek: Smash n'' Crash Racing offers high-speed fun on the GBA. Use unique character abilities and weapons to gain the lead on tracks inspired by the movie locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shrek---swamp-kart-speedway-uvenom', 'GAMEBOYADVANCE', 'Shrek - Swamp Kart Speedway (U)(Venom)', '2002', 'Racing', 'TDK Mediactive', '4', 'Cartoon Kart Racing', 'Top-down kart racer with environmental obstacles.', 'Be the fastest racer in the swamp and win the tournament.', 'Classic kart racing action with a Shrek twist.', 'Shrek: Swamp Kart Speedway features 8 playable characters and multiple tracks. Drift through the muck and use power-ups to leave your opponents in the dust in this handheld racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shrek-2---beg-for-mercy-erising-sun', 'GAMEBOYADVANCE', 'Shrek 2 - Beg for Mercy (E)(Rising Sun)', '2004', 'Action', 'Vicarious Visions', '1', 'Platformer Action Adventure', 'Side-scrolling action with stealth and puzzle elements.', 'Help Puss in Boots and Shrek rescue Princess Fiona.', 'Polished movie-based adventure with multiple heroes.', 'Shrek 2: Beg for Mercy focuses on the fan-favorite Puss in Boots. Use his agility and sword skills to navigate tricky levels and solve puzzles in this charming movie tie-in.');
