INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shrek-2-erising-sun', 'GAMEBOYADVANCE', 'Shrek 2 (E)(Rising Sun)', '2004', 'Action', 'Vicarious Visions', '1', 'Movie-Based Platformer', '2D side-scrolling platformer with team-switching mechanics.', 'Follow the plot of the second movie and save the kingdom.', 'Fun and faithful movie adaptation for GBA.', 'Shrek 2 lets you switch between characters like Shrek, Donkey, and Puss in Boots. Each character has unique skills needed to bypass obstacles in this vibrant handheld adventure.');
