INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silvanian-family-yousei-no-stick-to-fushigi-no-marroine-no-onnanoko-jrising-sun', 'GAMEBOYADVANCE', 'Silvanian Family Yousei no Stick to Fushigi no Marroine no Onnanoko (J)(Rising Sun)', '2004', 'Simulation', 'Marvelous Interactive', '1', 'Life Simulation Adventure', 'Life simulation and adventure featuring the Sylvanian characters.', 'Explore a magical forest and help your animal friends.', 'Adorable and cozy Sylvanian Families adventure.', 'Silvanian Family: Yousei no Stick is a sweet and accessible game for younger players. Explore a vibrant world, complete friendly tasks, and interact with the beloved doll characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silver-the-hedgehog-over-emerl', 'GAMEBOYADVANCE', 'Silver the Hedgehog over Emerl', '2006', 'Action', 'Fan Made', '1', 'Platformer Hack', '2D action-fighting game featuring Sonic the Hedgehog characters.', 'Master Silver''s psychic powers and win the tournament.', 'Fan-made RomHack featuring Silver the Hedgehog.', 'Silver the Hedgehog over Emerl is a creative modification of Sonic Battle. Play as Silver with psychic-based moves and custom sprites in this fast-paced GBA arena fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sim-city-2000-etrashman', 'GAMEBOYADVANCE', 'Sim City 2000 (E)(TrashMan)', '2003', 'Simulation', 'Maxis', '1', 'City Management Simulation', 'City-building simulation and urban management.', 'Design, build, and manage a thriving metropolis.', 'The definitive portable version of the classic sim.', 'Sim City 2000 on GBA is a remarkably deep port. Manage zoning, taxes, and infrastructure while dealing with disasters to create the ultimate city in this complex strategy masterpiece.');
