INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snap-kids-jcezar', 'GAMEBOYADVANCE', 'Snap Kids (J)(Cezar)', '2001', 'Action', 'Compile', '1', 'Cartoon Action Platformer', 'Photography-based RPG with monster collection.', 'Capture photos of monsters to build your deck and battle.', 'A creative "Snap and Battle" JRPG adventure.', 'Snap Kids is a unique GBA title that combines photography with monster-battling RPG mechanics. Explore a vibrant world, find rare creatures, and "capture" them with your camera to use in strategic battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snes-rainbow-road-in-mario-kart-xxl', 'GAMEBOYADVANCE', 'SNES Rainbow Road in Mario Kart XXL', '2005', 'Racing', 'Fan Made', '1', 'Mario Kart Track Hack', 'Pseudo-3D kart racing with high-difficulty tracks.', 'Master the legendary Rainbow Road and win the cup.', 'A colorful SNES-themed expansion for Mario Kart.', 'SNES Rainbow Road in Mario Kart XXL brings the most iconic and challenging track from the Super Nintendo era to the GBA. Experience high-speed drifting and classic obstacles in this vibrant retro tribute.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snood-eindependent', 'GAMEBOYADVANCE', 'Snood (E)(Independent)', '2000', 'Puzzle', 'Snood Inc.', '2', 'Arcade Bubble Puzzle', 'Puzzle-shooter with matching and gravity mechanics.', 'Launch Snoods to match three or more and clear the board.', 'The addictive and quirky cult classic puzzle game.', 'Snood is a puzzle phenomenon that tests your aim and logic. With various difficulty levels and unique characters, it offers endless hours of "just one more round" gameplay on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snood-umode7', 'GAMEBOYADVANCE', 'Snood (U)(Mode7)', '2000', 'Puzzle', 'Snood Inc.', '2', 'Arcade Bubble Puzzle', 'Puzzle-shooter with matching and gravity mechanics.', 'Launch Snoods to match three or more and clear the board.', 'The addictive and quirky cult classic puzzle game.', 'Snood is a puzzle phenomenon that tests your aim and logic. With various difficulty levels and unique characters, it offers endless hours of "just one more round" gameplay on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snood-2---on-vacation-erising-sun', 'GAMEBOYADVANCE', 'Snood 2 - On Vacation (E)(Rising Sun)', '2001', 'Puzzle', 'Snood Inc.', '2', 'Arcade Bubble Puzzle', 'Puzzle-shooter with themed levels and new characters.', 'Help the Snoods enjoy their vacation by clearing puzzle boards.', 'A fun, holiday-themed sequel to the puzzle hit.', 'Snood 2: On Vacation takes the classic gameplay to new exotic locations. Featuring updated graphics and creative level layouts, it’s a refreshing expansion of the addictive Snood formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snood-2---snoods-on-vacation-usir-vg', 'GAMEBOYADVANCE', 'Snood 2 - Snoods On Vacation (U)(Sir VG)', '2001', 'Puzzle', 'Snood Inc.', '2', 'Arcade Bubble Puzzle', 'Puzzle-shooter with themed levels and new characters.', 'Help the Snoods enjoy their vacation by clearing puzzle boards.', 'A fun, holiday-themed sequel to the puzzle hit.', 'Snood 2: On Vacation takes the classic gameplay to new exotic locations. Featuring updated graphics and creative level layouts, it’s a refreshing expansion of the addictive Snood formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soccer-kid-uvenom', 'GAMEBOYADVANCE', 'Soccer Kid (U)(Venom)', '2002', 'Platformer', 'Microids', '1', 'Side-Scrolling Platformer', '2D platformer with a soccer ball combat mechanic.', 'Use your soccer ball to defeat enemies and reclaim the trophy.', 'Creative platformer where a soccer ball is your weapon.', 'Soccer Kid is a unique action platformer where you must juggle and kick a soccer ball to solve puzzles and defeat bosses. Travel the world in this colorful and challenging GBA port of the Amiga classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-smk', 'GAMEBOYADVANCE', 'Sonic (SMK)', '1991', 'Platformer', 'Fan Made', '1', 'Classic Platformer', 'High-speed 2D side-scrolling platformer.', 'Collect rings and reach the goal at supersonic speeds.', 'A classic Sonic experience on the GBA.', 'Sonic (SMK) is a refined fan-version of the high-speed platforming formula. Experience the thrill of momentum-based gameplay and classic zone layouts with polished GBA physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-3---fighter-sonic-unl', 'GAMEBOYADVANCE', 'Sonic 3 - Fighter Sonic (Unl)', '2003', 'Action', 'Fan Made', '1', 'Platformer Hack', '2D side-scrolling platformer with modified sprites.', 'Defeat Eggman with a more aggressive "Fighter" Sonic.', 'A fast-paced combat-heavy Sonic modification.', 'Sonic 3 - Fighter Sonic (Unl) is a unique unlicensed take on the series. Featuring modified combat animations and faster movement, it offers a more aggressive style of play compared to the original titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-elightforce', 'GAMEBOYADVANCE', 'Sonic Advance (E)(Lightforce)', '2001', 'Platformer', 'Sonic Team', '1', 'High-Speed Platformer', 'High-speed 2D platformer with multiple playable characters.', 'Stop Dr. Eggman and collect the Chaos Emeralds.', 'The triumphant return of classic Sonic to handhelds.', 'Sonic Advance brings the original Genesis-style gameplay to GBA. Choose between Sonic, Tails, Knuckles, or Amy, each with unique abilities, in this beautifully animated and fast-paced platformer.');
