INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-1:-tweaked', 'GAMEBOYADVANCE', 'Sonic Advance 1: Tweaked', '2001', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'High-speed 2D platformer with balance and QoL fixes.', 'Experience a more balanced version of Sonic''s first GBA outing.', 'A polished and "tweaked" version of Sonic Advance.', 'Sonic Advance 1: Tweaked improves the classic game by adjusting physics, fixing minor bugs, and refining the difficulty. It’s the perfect way to experience the first entry with modern refinements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-2---lower-sp-ring-requirement', 'GAMEBOYADVANCE', 'Sonic Advance 2 - Lower SP Ring Requirement', '2002', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'High-speed 2D platformer with modified progression.', 'Unlock Special Stages more easily to get the Chaos Emeralds.', 'A QoL hack that makes 100% completion more accessible.', 'Sonic Advance 2 - Lower SP Ring Requirement is designed for players who want to experience the Super Sonic content without the extreme grind. Enjoy the high-speed action with a more relaxed unlock system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-2-epatience', 'GAMEBOYADVANCE', 'Sonic Advance 2 (E)(Patience)', '2002', 'Platformer', 'Sonic Team', '1', 'High-Speed Platformer', 'Ultra high-speed 2D platformer with momentum focus.', 'Race through massive levels and defeat Eggman''s machines.', 'The fastest and most intense Sonic entry on GBA.', 'Sonic Advance 2 doubles down on speed. Featuring the new "boost" mechanic and the debut of Cream the Rabbit, this title offers some of the most exhilarating and visually impressive stages on the system.');
