INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-3---adv1-edit', 'GAMEBOYADVANCE', 'Sonic Advance 3 - Adv1 Edit', '2004', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'High-speed 2D platformer with tag-team mechanics.', 'Use character duos to solve puzzles and clear stages.', 'A creative edit of the third Sonic Advance entry.', 'Sonic Advance 3 - Adv1 Edit mixes elements of the first game into the third''s structure. Experience the tag-team mechanics with a more classic aesthetic and level-design philosophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-3-etrashman', 'GAMEBOYADVANCE', 'Sonic Advance 3 (E)(TrashMan)', '2004', 'Platformer', 'Sonic Team', '1', 'High-Speed Platformer', 'High-speed 2D platformer with tag-team mechanics.', 'Experiment with character pairings to reach the goal.', 'The ultimate team-based Sonic adventure on GBA.', 'Sonic Advance 3 features a deep tag-team system where your choice of partner changes your abilities. Explore expansive zones and discover secret paths in this content-rich finale to the Advance trilogy.');
