INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-double-take', 'GAMEBOYADVANCE', 'Sonic Advance Double Take', '2004', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'High-speed 2D platformer with dual-view or palette swaps.', 'Experience the GBA Sonic levels with a fresh visual twist.', 'A creative visual modification of Sonic Advance.', 'Sonic Advance Double Take offers a unique look at the levels you know, with altered color palettes and refined sprites. It’s a great way for veterans to play through the game with a new aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-souped-up', 'GAMEBOYADVANCE', 'Sonic Advance Souped Up', '2004', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'High-speed 2D platformer with enhanced speed and physics.', 'Navigate classic levels with a "Souped Up" engine.', 'A high-performance overhaul for Sonic Advance.', 'Sonic Advance Souped Up increases the speed and responsiveness of the game. If you felt the original wasn''t fast enough, this mod delivers the "blast processing" feel to your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-x', 'GAMEBOYADVANCE', 'Sonic Advance X', '2004', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'High-speed 2D platformer featuring crossover elements.', 'Blaze through levels with characters and moves from other games.', 'A modern "Ultimate" style GBA Sonic RomHack.', 'Sonic Advance X is a massive project that incorporates moves from the modern era into the GBA engine. Enjoy a faster, more versatile Sonic with a high-quality move-set.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-advance-x-neo-green-hill-zone-demo', 'GAMEBOYADVANCE', 'Sonic Advance X Neo Green Hill Zone Demo', '2004', 'Platformer', 'Fan Made', '1', 'Platformer Hack', 'Technical demo of a modern GBA Sonic engine.', 'Explore the reimagined Neo Green Hill Zone.', 'A stunning fan-made tech demo of Sonic on GBA.', 'Sonic Advance X Neo Green Hill Zone Demo showcases what a modern fan-engine can do on the GBA hardware. Featuring beautiful backgrounds and fluid movement, it’s a must-see for fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---dark-sonic-20', 'GAMEBOYADVANCE', 'Sonic Battle - Dark Sonic 2.0', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with custom character forms.', 'Dominate the battle arena as the powerful Dark Sonic.', 'A shadow-drenched combat mod for Sonic Battle.', 'Sonic Battle - Dark Sonic 2.0 replaces the standard Sonic with his darker, more powerful form. Featuring custom animations and increased damage, it’s a fierce take on the GBA brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---hyper-shadic-over-sonic-version-12', 'GAMEBOYADVANCE', 'Sonic Battle - Hyper Shadic Over Sonic Version 1.2', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with legendary fusion characters.', 'Win the tournament using the ultimate fusion of Sonic and Shadow.', 'A high-quality combat mod featuring Hyper Shadic.', 'Sonic Battle - Hyper Shadic Over Sonic brings the fan-favorite fusion to the arena. With a completely new move-set and stunning sprites, it transforms the battle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---hyper-sonic', 'GAMEBOYADVANCE', 'Sonic Battle - Hyper Sonic', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with invincible "Hyper" stats.', 'Defeat every opponent with the glowing power of Hyper Sonic.', 'An overpowered and flashy mod for Sonic Battle.', 'Sonic Battle - Hyper Sonic gives you the ultimate power. With flashing sprites and massive speed boosts, you can tear through the competition in the GBA''s best fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---overpowered', 'GAMEBOYADVANCE', 'Sonic Battle - Overpowered', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with extremely high stats and moves.', 'Crush the competition with an "Overpowered" roster.', 'A chaotic and fun combat mod for Sonic Battle.', 'Sonic Battle - Overpowered is designed for pure destruction. Experience modified stats that allow for insane combos and instant knockouts in this fast-paced arena fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---super-shadow-buffed', 'GAMEBOYADVANCE', 'Sonic Battle - Super Shadow Buffed', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with buffed character stats.', 'Dominate the arena with a significantly powered-up Super Shadow.', 'A high-power combat mod for Shadow fans.', 'Sonic Battle - Super Shadow Buffed takes the ultimate lifeform to the next level. Enjoy increased speed, devastating damage, and custom gold sprites in this intense arena brawler modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---super-shadow-vanilla', 'GAMEBOYADVANCE', 'Sonic Battle - Super Shadow Vanilla', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with balanced transformation.', 'Fight as Super Shadow with original game balancing.', 'A clean and classic Super Shadow mod for Sonic Battle.', 'Sonic Battle - Super Shadow Vanilla provides a balanced way to play as the golden hedgehog. It integrates the transformation seamlessly without breaking the game''s core combat mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---super-sonic-20', 'GAMEBOYADVANCE', 'Sonic Battle - Super Sonic 2.0', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with updated Super Sonic mechanics.', 'Win the tournament using the refined powers of Super Sonic.', 'An improved Super Sonic mod with custom animations.', 'Sonic Battle - Super Sonic 2.0 features polished sprites and a more fluid move-set for Sonic''s golden form. Experience a better flow in combat while wielding the power of the Chaos Emeralds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---super-sonic-3', 'GAMEBOYADVANCE', 'Sonic Battle - Super Sonic 3', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with evolved transformation.', 'Master the third evolution of the Super Sonic mod series.', 'A refined and powerful Super Sonic combat experience.', 'Sonic Battle - Super Sonic 3 offers a more aggressive playstyle and updated visual effects. It’s a perfect mod for players looking for a high-speed, high-impact version of the Blue Bomber.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---super-sonic-4', 'GAMEBOYADVANCE', 'Sonic Battle - Super Sonic 4', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with ultimate transformation features.', 'Reach the pinnacle of power with the Super Sonic 4 mod.', 'The most advanced version of the Super Sonic mod series.', 'Sonic Battle - Super Sonic 4 brings peak performance to the GBA arena. Featuring the most refined move-set and fastest dash speeds, it’s the definitive way to play as Super Sonic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---super-tails', 'GAMEBOYADVANCE', 'Sonic Battle - Super Tails', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler featuring a rare transformation.', 'Battle with the golden aura and enhanced flying skills of Super Tails.', 'A unique mod featuring the powerful Super Tails.', 'Sonic Battle - Super Tails gives the loyal sidekick his glowing golden form. Use enhanced flight and rapid-fire attacks to outmaneuver your rivals in this creative GBA mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---the-ultimate-hyper-knuckles', 'GAMEBOYADVANCE', 'Sonic Battle - The Ultimate Hyper Knuckles.', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with invincible "Hyper" power-ups.', 'Crush your enemies with the pink-glowing Hyper Knuckles.', 'An overpowered and flashy mod for the ultimate guardian.', 'Sonic Battle - The Ultimate Hyper Knuckles features insane strength and custom hyper-glow sprites. Experience the guardian of the Master Emerald like never before in this intense brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle---ultra-instinct-sonic', 'GAMEBOYADVANCE', 'Sonic Battle - Ultra Instinct Sonic', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with high-speed dodging mechanics.', 'Master the "Ultra Instinct" state to dodge every attack.', 'A crossover mod bringing UI mechanics to Sonic.', 'Sonic Battle - Ultra Instinct Sonic focuses on speed and reaction time. Dodge attacks automatically and strike back with divine speed in this anime-inspired GBA modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle-eindependent', 'GAMEBOYADVANCE', 'Sonic Battle (E)(Independent)', '2003', 'Fighting', 'Sonic Team', '2', 'Arena Fighter', '2D arena-based fighter with isometric movement and deep customization.', 'Master various fighting styles and uncover the story of Emerl.', 'The definitive Sonic fighting game on GBA.', 'Sonic Battle is a unique entry in the series, featuring 3D-style arenas and 2D sprites. Collect and equip moves to customize your robot friend, Emerl, in this deep and engaging combat title.');
