INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle-enhanced', 'GAMEBOYADVANCE', 'Sonic Battle Enhanced', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena-based fighter with quality-of-life improvements.', 'Enjoy a smoother and more balanced version of the original combat.', 'A polished and refined version of the GBA classic.', 'Sonic Battle Enhanced tweaks the original gameplay to fix bugs and improve move-set balance. It’s the best way for veterans to revisit the tactical combat of the Emerl saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle-multiverse-pack-2020', 'GAMEBOYADVANCE', 'Sonic Battle Multiverse pack 2020', '2020', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with a massive character and move expansion.', 'Battle through a multiverse of Sonic characters and forms.', 'A massive 2020 compilation mod for Sonic Battle.', 'Sonic Battle Multiverse Pack 2020 is a dream for mod fans. It packs numerous new characters, forms, and stages into the GBA engine for the ultimate handheld crossover experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-battle:stream-the-hedgehog!!!', 'GAMEBOYADVANCE', 'Sonic Battle:Stream the hedgehog!!!', '2003', 'Fighting', 'Fan Made', '2', 'Arena Fighter Hack', '2D arena brawler with a custom character focus.', 'Play through the tournament as a unique "Stream" themed hedgehog.', 'A creative fan-character mod for Sonic Battle.', 'Sonic Battle: Stream the Hedgehog adds a fresh personality to the roster. Master a unique move-set and explore a new way to play the classic GBA brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-exe-version-20', 'GAMEBOYADVANCE', 'Sonic Exe Version 2.0', '2003', 'Action', 'Horror Fan Game', '1', 'Action Hack', '2D side-scrolling platformer with horror elements.', 'Survive the corrupted levels and escape the nightmare.', 'A GBA adaptation of the viral Sonic creepypasta.', 'Sonic Exe Version 2.0 brings the infamous horror project to the GBA. Navigate through glitched environments and avoid the terrifying "EXE" in this atmospheric and dark modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-in-dragon-ball:-advanced-adventure', 'GAMEBOYADVANCE', 'Sonic in Dragon Ball: Advanced Adventure', '2004', 'Action-Adventure', 'Fan Made', '1', 'Crossover Action Adventure', 'Side-scrolling beat ''em up with Dragon Ball mechanics.', 'Play as Sonic in the world of Goku and friends.', 'A high-speed Sonic mod of Dragon Ball: Advanced Adventure.', 'Sonic in Dragon Ball: Advanced Adventure swaps Goku for the Blue Blur. Use Sonic''s speed to zip through the Red Ribbon Army and fight legendary martial artists in this fluid action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-pinball-party-eendless-piracy', 'GAMEBOYADVANCE', 'Sonic Pinball Party (E)(Endless Piracy)', '2002', 'Pinball', 'Sonic Team', '4', 'Arcade Pinball', 'Pinball simulation with Sonic-themed tables and mini-games.', 'Score points and beat bosses in vibrant Sonic worlds.', 'The most fun and energetic pinball game on GBA.', 'Sonic Pinball Party features tables based on Sonic, NiGHTS, and Samba de Amigo. Master the physics-based gameplay to unlock secrets and enjoy the colorful SEGA atmosphere on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-pinball-party-jrising-sun', 'GAMEBOYADVANCE', 'Sonic Pinball Party (J)(Rising Sun)', '2002', 'Pinball', 'Sonic Team', '4', 'Arcade Pinball', 'Pinball simulation with Sonic-themed tables and mini-games.', 'Score points and beat bosses in vibrant Sonic worlds.', 'The most fun and energetic pinball game on GBA.', 'Sonic Pinball Party features tables based on Sonic, NiGHTS, and Samba de Amigo. Master the physics-based gameplay to unlock secrets and enjoy the colorful SEGA atmosphere on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-pinball-party-uvenom', 'GAMEBOYADVANCE', 'Sonic Pinball Party (U)(Venom)', '2002', 'Pinball', 'Sonic Team', '4', 'Arcade Pinball', 'Pinball simulation with Sonic-themed tables and mini-games.', 'Score points and beat bosses in vibrant Sonic worlds.', 'The most fun and energetic pinball game on GBA.', 'Sonic Pinball Party features tables based on Sonic, NiGHTS, and Samba de Amigo. Master the physics-based gameplay to unlock secrets and enjoy the colorful SEGA atmosphere on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog---genesis-utrashman', 'GAMEBOYADVANCE', 'Sonic The Hedgehog - Genesis (U)(Trashman)', '1991', 'Platformer', 'Sega', '1', 'Classic Platformer', '2D side-scrolling platformer (Anniversary Port).', 'Experience the original 1991 adventure on your GBA.', 'The portable 15th-anniversary port of the first Sonic.', 'Sonic The Hedgehog: Genesis brings the game that started it all to the GBA. Explore Green Hill Zone and defeat Dr. Robotnik in this classic 16-bit platformer adapted for handheld play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonicmon-fire-red', 'GAMEBOYADVANCE', 'Sonicmon Fire Red', '2004', 'RPG', 'Fan Made', '1', 'Monster Collecting Hack', 'Creature-collection RPG with a Sonic-themed world.', 'Catch and train Sonic-themed "monsters" to become the champion.', 'A unique Sonic-themed RomHack of Pokémon Fire Red.', 'Sonicmon Fire Red replaces traditional Pokémon with characters from the Sonic universe. Explore a modified Kanto region, battle Gym Leaders, and evolve your favorite Sonic characters in this RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sorry-aggravation-scrabble-junior-ufonz', 'GAMEBOYADVANCE', 'Sorry, Aggravation, Scrabble Junior (U)(Fonz)', '2001', 'Board Game', 'Hasbro', '4', 'Digital Board Game Collection', 'Compilation of three classic family board games.', 'Win at Sorry!, Aggravation, and Scrabble Junior.', 'A perfect GBA pack for family game nights.', 'This collection brings three tabletop favorites to the GBA. Whether you''re sliding in Sorry! or spelling in Scrabble Junior, it''s a great digital pack for younger players and fans of classic board games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-channel-5---ulalas-cosmic-attack-eindependent', 'GAMEBOYADVANCE', 'Space Channel 5 - Ulala''s Cosmic Attack (E)(Independent)', '2003', 'Rhythm Action', 'Sega', '1', 'Music Rhythm Action', 'Rhythm-action adventure with music-based prompts.', 'Defeat the Morolians and save the galaxy through dance.', 'SEGA’s stylish and funky rhythm classic on GBA.', 'Space Channel 5: Ulala''s Cosmic Attack brings the 3D Dreamcast hit to 2D. Follow the rhythm, mimic the poses, and help Ulala report on the alien invasion in this colorful and catchy GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-channel-5---ulalas-cosmic-attack-umode7', 'GAMEBOYADVANCE', 'Space Channel 5 - Ulala''s Cosmic Attack (U)(Mode7)', '2003', 'Rhythm Action', 'Sega', '1', 'Music Rhythm Action', 'Rhythm-action adventure with music-based prompts.', 'Defeat the Morolians and save the galaxy through dance.', 'SEGA’s stylish and funky rhythm classic on GBA.', 'Space Channel 5: Ulala''s Cosmic Attack brings the 3D Dreamcast hit to 2D. Follow the rhythm, mimic the poses, and help Ulala report on the alien invasion in this colorful and catchy GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-hexcite-x-jperversion', 'GAMEBOYADVANCE', 'Space Hexcite X (J)(Perversion)', '2003', 'Puzzle', 'Sega', '1', 'Block Puzzle', 'Strategic tile-matching puzzle game with sci-fi themes.', 'Clear the hexagonal board by matching colored gems.', 'A unique and challenging sci-fi hexagonal puzzle game.', 'Space Hexcite X is a polished Japanese puzzle title. Master the hexagonal logic and use special items to clear increasingly difficult levels in this visually striking and addictive GBA game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-feternity', 'GAMEBOYADVANCE', 'Space Invaders (F)(Eternity)', '1978', 'Shooter', 'Taito', '1', 'Fixed Shooter', 'Fixed-shooter arcade classic with updated visuals.', 'Defend Earth from waves of descending alien invaders.', 'The legendary arcade shooter in your pocket.', 'Space Invaders on GBA offers a faithful recreation of the 1978 original. Blast the aliens, hide behind bunkers, and experience the simple but challenging gameplay that defined the industry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-uvenom', 'GAMEBOYADVANCE', 'Space Invaders (U)(Venom)', '1978', 'Shooter', 'Taito', '1', 'Fixed Shooter', 'Fixed-shooter arcade classic with updated visuals.', 'Defend Earth from waves of descending alien invaders.', 'The legendary arcade shooter in your pocket.', 'Space Invaders on GBA offers a faithful recreation of the 1978 original. Blast the aliens, hide behind bunkers, and experience the simple but challenging gameplay that defined the industry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-ex-jeurasia', 'GAMEBOYADVANCE', 'Space Invaders EX (J)(Eurasia)', '2000', 'Shooter', 'Taito', '1', 'Enhanced Fixed Shooter', 'Modernized fixed-shooter with 3D-style graphics and power-ups.', 'Survive intense waves of aliens in a futuristic setting.', 'A flashy and modern evolution of the Space Invaders formula.', 'Space Invaders EX (Extreme) features fast-paced shooting, vibrant effects, and powerful weapon upgrades. It’s a high-energy take on the classic that feels fresh and exciting on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedball-2-eeurasia', 'GAMEBOYADVANCE', 'Speedball 2 (E)(Eurasia)', '1991', 'Sports', 'The Bitmap Brothers', '2', 'Futuristic Sports', 'Futuristic sports simulation with high-impact combat.', 'Outscore your rivals in the brutal arena of future-ball.', 'The legendary cyberpunk sports classic on GBA.', 'Speedball 2 (Brutal Deluxe) is a fast-paced mix of handball and brawling. Manage your team, upgrade players, and use violence to win the championship in this polished port of the Amiga hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man---battle-for-new-york-erising-sun', 'GAMEBOYADVANCE', 'Spider-Man - Battle for New York (E)(Rising Sun)', '2004', 'Action Platformer', 'Vicarious Visions', '1', 'Action Platformer', 'Side-scrolling action adventure with a dual-character mechanic.', 'Play as both Spider-Man and the Green Goblin in a battle for NYC.', 'A unique perspective on the Spider-Man universe.', 'Spider-Man: Battle for New York lets you experience the story from both sides. Master Spidey''s webs and the Goblin''s bombs in this action-packed platformer with impressive GBA sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man---battle-for-new-york-urising-sun', 'GAMEBOYADVANCE', 'Spider-Man - Battle For New York (U)(Rising Sun)', '2004', 'Action Platformer', 'Vicarious Visions', '1', 'Action Platformer', 'Side-scrolling action adventure with a dual-character mechanic.', 'Play as both Spider-Man and the Green Goblin in a battle for NYC.', 'A unique perspective on the Spider-Man universe.', 'Spider-Man: Battle for New York lets you experience the story from both sides. Master Spidey''s webs and the Goblin''s bombs in this action-packed platformer with impressive GBA sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man---der-film-gsupplex', 'GAMEBOYADVANCE', 'Spider-Man - Der Film (G)(Supplex)', '2002', 'Action Adventure', 'Digital Eclipse', '1', 'Action Adventure', 'Side-scrolling action platformer with web-swinging mechanics.', 'Defeat the Green Goblin and protect New York City.', 'Official movie-based Spider-Man action on GBA.', 'Spider-Man: The Movie (Der Film) brings the cinematic excitement to your handheld. Swing through Manhattan, crawl on walls, and use Spider-Sense to defeat thugs and the Green Goblin in this polished 2D action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man---mysterios-menace-jcezar', 'GAMEBOYADVANCE', 'Spider-Man - Mysterio''s Menace (J)(Cezar)', '2001', 'Action Platformer', 'Vicarious Visions', '1', 'Action Platformer', 'Side-scrolling action platformer with exploration.', 'Stop Mysterio''s illusions and defeat iconic Marvel villains.', 'One of the best Spider-Man games on the Game Boy Advance.', 'Spider-Man: Mysterio''s Menace features tight controls and beautiful graphics. Explore multi-path levels, unlock new suits, and battle Rhino, Hammerhead, and Mysterio in this high-quality GBA adventure.');
