INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-3-eindependent', 'GAMEBOYADVANCE', 'Spider-Man 3 (E)(Independent)', '2007', 'Action Adventure', 'Vicarious Visions', '1', 'Action Adventure', 'Side-scrolling action with the Black Suit mechanic.', 'Save New York from the New Goblin, Sandman, and Venom.', 'Intense action featuring the iconic Black Suit.', 'Spider-Man 3 on GBA introduces the Black Suit, giving Spidey more aggressive moves and power. Navigate urban levels and engage in epic boss fights against the movie''s main villains in this high-stakes platformer.');
