INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spirit---der-wilde-mustang-gpatientz', 'GAMEBOYADVANCE', 'Spirit - Der Wilde Mustang (G)(Patientz)', '2002', 'Action Adventure', 'Lucky Chicken Games', '1', 'Platform Adventure', '2D adventure with exploration and stealth elements.', 'Help Spirit protect his herd and find his way back home.', 'Charming adventure based on the DreamWorks film.', 'Spirit: Stallion of the Cimarron (Der Wilde Mustang) lets you explore the vast wilderness. Avoid danger, help other horses, and experience the story of the wild mustang in this beautifully animated GBA game.');
