INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spirits-and-spells-uhyperion', 'GAMEBOYADVANCE', 'Spirits and Spells (U)(Hyperion)', '2003', 'Action RPG', 'Square Enix', '1', 'Isometric Action RPG', 'Side-scrolling action platformer with spooky themes.', 'Guide Alicia and Greg through the Land of the Dead.', 'Atmospheric and colorful spooky platformer.', 'Spirits and Spells (known as Castleween) is a charming adventure. Switch between characters to solve puzzles and defeat ghosts in this visually impressive and festive GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spongebob-and-friends---attack-of-the-toybots-eindependent', 'GAMEBOYADVANCE', 'SpongeBob and Friends - Attack of the Toybots (E)(Independent)', '2007', 'Action Platformer', 'WayForward', '1', 'Platform Action', 'Action-adventure with multiple Nickelodeon heroes.', 'Stop Professor Calamitous and his army of Toybots.', 'Crossover adventure featuring Nicktoons stars.', 'SpongeBob and Friends: Attack of the Toybots features SpongeBob, Danny Phantom, and more. Use giant mech suits and character skills to fight through robotic levels in this fun handheld crossover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spongebob-squarepants---battle-for-bikini-bottom-eindependent', 'GAMEBOYADVANCE', 'SpongeBob SquarePants - Battle for Bikini Bottom (E)(Independent)', '2003', 'Action Platformer', 'Heavy Iron Studios', '1', 'Platform Action', '2D side-scrolling platformer with various mini-games.', 'Save Bikini Bottom from Plankton''s robot invasion.', 'High-quality platforming with the SpongeBob gang.', 'SpongeBob SquarePants: Battle for Bikini Bottom on GBA features diverse levels and fun challenges. Help SpongeBob, Patrick, and Sandy defend their home in this vibrant and humorous adventure.');
