INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spongebob-squarepants-and-friends---battle-for-volcano-island-elightforce', 'GAMEBOYADVANCE', 'SpongeBob SquarePants and Friends - Battle for Volcano Island (E)(LightForce)', '2006', 'Action Platformer', 'Nickelodeon', '1', 'Platform Action', 'Action-adventure with character switching and puzzles.', 'Stop Mawgu and save Volcano Island from corruption.', 'Tropical island adventure featuring Nicktoons heroes.', 'SpongeBob and Friends: Battle for Volcano Island brings a team of heroes to the GBA. Use the unique abilities of SpongeBob and Danny Phantom to solve puzzles and defeat jungle enemies.');
