INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-illustrated-for-kids---baseball-uvenom', 'GAMEBOYADVANCE', 'Sports Illustrated For Kids - Baseball (U)(Venom)', '2001', 'Sports', 'Vicarious Visions', '4', 'Baseball', 'Arcade-style baseball simulation with customizable teams.', 'Win the world championship and outplay rival teams.', 'Accessible and fun handheld baseball action.', 'Sports Illustrated For Kids: Baseball offers a streamlined take on the diamond. Perfect for quick sessions, it features colorful sprites, simple controls, and the competitive spirit of the SI for Kids brand.');
